import React, { useEffect, useState } from "react";

function Risks({ setToken }) {
  const [risks, setRisks] = useState([]);
  const [error, setError] = useState("");

  useEffect(() => {
    // fetch risks logic...
  }, []);

  return (
    <div className="container">
      <h2>Risks</h2>
      {error && <p style={{ color: "red" }}>{error}</p>}
      {risks.length > 0 ? (
        <table>
          <thead>
            <tr>
              <th>ID</th>
              <th>Description</th>
              <th>Severity</th>
            </tr>
          </thead>
          <tbody>
            {risks.map((risk) => (
              <tr key={risk.id}>
                <td>{risk.id}</td>
                <td>{risk.description}</td>
                <td>{risk.severity}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        !error && <p>No risks found.</p>
      )}
    </div>
  );
}

export default Risks;
